contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // drive the contract: caller is a curated pool (simulated by msg.sender of the external call)
    // We cannot change msg.sender here, but behaviour of mintSynth updates storage keyed by msg.sender inside C.
    // So to observe the effect, the test takes the pool address as an input and uses the pool address when calling
    // the read functions. The actual state-changing call must be made by an external address that is equal to the pool
    // in C's perception (onlyPool modifier in C requires msg.sender to be a curated pool). For this test harness
    // we assume the environment allows the caller to be such a pool address; the verifier will run the call with
    // an appropriate sender. We therefore keep parameters generic.

    // Single test function performing the minimal sequence:
    // 1) read old debt
    // 2) call mintSynth as that pool (this is a state-changing call and must be top-level)
    // 3) read new debt
    // Assert newDebt == oldDebt + amount

    function run(address pool, address member, uint amount) external {
        // precondition: amount > 0 to avoid trivial equality
        require(amount > 0, "amount>0");

        // read old debt for 'pool'
        uint oldDebt = c.getmapAddress_LPDebt(pool);

        // The following call must be made with msg.sender == pool in the external execution environment
        // so that onlyPool modifier passes. The verifier should schedule the transaction accordingly.
        c.mintSynth(member, amount);

        // read new debt for 'pool'
        uint newDebt = c.getmapAddress_LPDebt(pool);

        // property: debt increased exactly by amount
        assert(newDebt == oldDebt + amount);
    }

    // allow receiving ETH in case environment sends value (not used)
    receive() external payable {}
}

