import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameters: an arbitrary address key and two amounts to simulate prior minting
    function testFuzz_property(address key, uint256 lpMintAmount, uint256 synthMintAmount) public {
        // keep values wide but avoid trivial overflow of balances in this simplified test
        lpMintAmount = bound(lpMintAmount, 0, type(uint128).max);
        synthMintAmount = bound(synthMintAmount, 0, type(uint128).max);

        // Setup: impersonate a pool (the contract expects onlyPool but our constructor set DEPLOYER to test contract, and pool checks factory; for this test we directly call C's mintSynth via vm.prank to simulate pool caller)
        // We will use address(this) as the pool (the test contract) since setUp used address(this) for DAO and LayerONE parameters in constructor

        // Before any external reads, record LP balance for key
        uint before = c.getmapAddress_LPBalance(key);

        // Simulate that the pool (address(this)) transfers LP tokens to C contract so that _getAddedLPAmount will detect added LP units.
        // Here we cannot actually increase the BEP20 balance of the pool token at address(key) because tokens are not real; instead we rely on the C contract's internal bookkeeping: mapSynth_LPBalance[msg.sender] increases by lpUnits in mintSynth.
        // Call mintSynth as if the pool mints synth to some member, which updates mapSynth_LPBalance and mapSynth_LPDebt.
        vm.prank(address(this));
        c.mintSynth(address(0xBEEF), lpMintAmount == 0 ? 1 : synthMintAmount);

        // After mintSynth, record LP balance for key (could be same unless key == pool)
        uint mid = c.getmapAddress_LPBalance(key);

        // Now call allowance (a pure/view) which must not mutate mapSynth_LPBalance for any key.
        // We choose two arbitrary addresses as parameters; fuzz these indirectly using the provided key and test contract
        address a = key;
        address b = address(this);

        // Call allowance and ignore its result; ensure it does not mutate the mapping
        try c.allowance(a, b) returns (uint256) {
            // no-op
        } catch {
            // allowance should not revert, but even if it did, we still check invariance on mapping after the call attempt
        }

        uint after = c.getmapAddress_LPBalance(key);

        // The universal property: allowance should not change mapSynth_LPBalance(key).
        // The reference implementation preserves this for all inputs; the mutant that flips += to -= in mintSynth can cause mapSynth_LPBalance to diverge for some inputs, so the fuzzer can find a counterexample and make this assert fail on the mutant.
        assertTrue(after == mid);
    }
}

