contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive minimal sequence: a pool (this test uses address(this) as the calling pool) calls mintSynth(member, amount)
    // We require that before calling, c.getmapAddress_LPBalance(pool) and c.getmapAddress_LPDebt(pool) are observed.
    // The property: after mintSynth is invoked by the pool, the stored LP balance for the pool is at least the previous balance
    // (i.e., minting never reduces the pool's recorded LP balance). This holds in P (which adds lpUnits) and is violated by M (which subtracts).

    function run_test(address member, uint amount) public {
        // preconditions to make mintSynth meaningful: amount > 0
        require(member != address(0));
        require(amount > 0);

        // observe before values
        uint beforeLP = c.getmapAddress_LPBalance(address(this));
        uint beforeDebt = c.getmapAddress_LPDebt(address(this));

        // CALL: this contract acts as a curated pool caller; invoke mintSynth
        c.mintSynth(member, amount);

        // observe after value
        uint afterLP = c.getmapAddress_LPBalance(address(this));
        uint afterDebt = c.getmapAddress_LPDebt(address(this));

        // Assert: afterLP >= beforeLP  (minting should not decrease recorded LP balance)
        assert(afterLP >= beforeLP);
    }

    // allow receiving tokens/ether if needed by external interactions
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address member, uint amount) public payable {
        // Require that the caller (a curated pool) would have added LP units > 0
        // We cannot call internal _getAddedLPAmount, but we can require that
        // the pool's current recorded LP balance is strictly less than its ERC20 balance
        // i.e., the pool contract (msg.sender for mintSynth) will observe added LP > 0.
        // The pool that calls mintSynth is the test caller here, so we use the provided `member`
        // parameter as the recipient; the pool address is address(this) when calling c.mintSynth.
        // However mintSynth in C expects msg.sender to be the pool. To simulate a curated pool,
        // the test cannot change msg.sender; instead we require that for the pool address we'll pass
        // in as the caller (we must call c.mintSynth from this contract, so msg.sender==address(this)).
        // Therefore ensure that the pool's ERC20 balance of its own LP token (the pool's address) is > recorded mapSynth_LPBalance.
        // We can observe recorded values via public getters getmapAddress_LPBalance and getmapAddress_LPDebt.
        require(c.getmapAddress_LPBalance(address(this)) < iBEP20(address(c)).balanceOf(address(this)) || true, true);
        // Note: Above require is a no-op placeholder to satisfy template when no extra precondition is needed.
        bool reverted;
        try c.mintSynth(member, amount) { reverted = false; } catch { reverted = true; }
        // General rule: when the pool has any newly added LP units (its ERC20 balance > recorded LP balance)
        // then mintSynth SHOULD NOT revert on the original contract P. We express this by checking
        // that if iBEP20(address(c)).balanceOf(address(this)) > c.getmapAddress_LPBalance(address(this)) then reverted==false.
        assert(!(iBEP20(address(c)).balanceOf(address(this)) > c.getmapAddress_LPBalance(address(this)) ) || reverted == false);
    }
    receive() external payable { }
}

